///Remarks details from Rem and Linf
function loadRemarks(ktsr,ptsr,idn,khatinType)
{
	document.getElementById("remarks").style.display="block";
	document.getElementById("poseser").style.display="none";
	document.getElementById("trustee").style.display="none";
	document.getElementById("map").style.display="none";
	var remDtlHtml=""; 
	$.post("RemarksDetailsAction_LandInfo.action",{ktsr :ktsr,ptsr : ptsr,idn:idn,radioKhatianDtlType : khatinType,
		 ajax : 'true'},function(data){	
			 if(data.exception){							
					jError(data.exception,'Error');						  		   
				}else{
			 document.getElementById("remarks").innerHTML="";
			 if(data.exception){
			    	document.getElementById("remarks").innerHTML = '<table class="table"><tr><td nowrap="nowrap"> <font size="8px" color="red">'+data.exception+'</font></td></tr></table>';
			 }else{
			    	document.getElementById("remarks").innerHTML=data.msgShow;}
				}
		 },"json");
	
	
	
}
function loadRemarksHtml(remLinfHtml){
	document.getElementById("remarks").style.display="block";
	document.getElementById("poseser").style.display="none";
	document.getElementById("trustee").style.display="none";
	document.getElementById("map").style.display="none";
	// Decode passed HTML if itâ??s URI encoded
    const decodedHtml = decodeURIComponent(remLinfHtml.replace(/\+/g, ' '));

    // Display in remarks div
    document.getElementById("remarks").innerHTML = decodedHtml;
}

